insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('sort-colours-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Sort Colours', 'An everyday activity that develops grasp-and-release control.', 8, '5–10 min', 'Coloured household objects', 'Sort household objects into 3 colour groups. Naming the colours correctly while sorting combines language and cognition.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('200-word-vocabulary-m22_24', 'communication'::domain, 'm22_24'::age_band, '200+ Word Vocabulary', 'A playful, repeatable activity for first words and vocabulary.', null, 'Ongoing', 'None', '200 words by 24 months is the benchmark (CDC). Under 50 words by 24 months is worth professional discussion.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('two-three-word-phrases-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Two- Three-Word Phrases', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'Mama, more water please.'' Three-word phrases mark a significant vocabulary and grammar step appearing 21–24 months.', 'Your toddler understands much more than they can say, and this closes that gap. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('use-i-me-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Use ''I'' ''Me''', 'An everyday activity that develops first words and understanding.', null, 'Ongoing', 'None', 'I want'' and ''Give me'' appearing means self-concept is strongly established. Model these forms throughout the day.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('ask-open-questions-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Ask Open Questions', 'A simple activity that builds first words and understanding.', 8, '5–10 min', 'None', 'What happened at the park today?'' Not ''Did you have fun?'' Open questions require memory, sequencing, and language simultaneously.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('story-prediction-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Story Prediction', 'A playful, repeatable activity for early narrative and vocabulary.', 8, '5–10 min', 'Book', 'During book reading, stop before a page turn: ''What do you think will happen next?'' Prediction requires language plus narrative cognition.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('name-colours-environment-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Name Colours Environment', 'An everyday activity that develops first words and vocabulary.', null, 'Ongoing', 'None', 'Not a colour worksheet: just naming colours of real objects throughout the day. Context makes the association stronger.', 'Your toddler understands much more than they can say, and this closes that gap. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('rhyming-play-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Rhyming Play', 'A simple activity that builds early narrative and vocabulary.', 7, '5–8 min', 'None', 'Cat (bat) sat: mat!'' Rhyming awareness at 24 months predicts reading readiness. Even partial awareness is worth celebrating.', 'Your toddler understands much more than they can say, and this closes that gap. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('describe-daily-events-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Describe Daily Events', 'A simple activity that builds first words and understanding.', 8, '5–10 min', 'None', 'At bedtime, ask child to tell you two things that happened today. This builds narrative language and episodic memory together.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('sort-size-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sort Size', 'A playful, repeatable activity for early sorting and matching.', 8, '5–10 min', 'Objects of two distinct sizes', 'Sort objects into two groups: big and small. Size concept develops through sorting, not worksheets.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sequence-daily-routine-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sequence Daily Routine', 'A playful, repeatable activity for early problem-solving and matching.', 7, '5–8 min', 'None', 'Ask: ''What do we do after breakfast? Then what?'' Three to four event sequence recall is the target at this age.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('complete-simple-pattern-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Complete Simple Pattern', 'An everyday activity that develops shape and spatial matching.', 7, '5–8 min', 'Coloured objects or blocks', 'Build a simple colour or shape pattern: red, blue, red, blue, and leave a gap. Can child predict what comes next?', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('concept-full-empty-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Concept Full Empty', 'A playful, repeatable activity for early problem-solving and matching.', 8, '5–10 min', 'Glass and water', 'Pour water into an empty glass; let child pour it back. ''Full. Empty. Full again.'' Concrete object manipulation precedes abstract concept.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('match-photo-person-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Match Photo Person', 'A simple activity that builds object permanence and searching.', 7, '5–8 min', 'Family photos', 'Show baby photos of family members. Can child identify who it is? Memory across time = abstract object permanence.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Piagetian developmental framework; Harvard Center on the Developing Child; IAP'),
  ('counting-one-to-one-correspondence-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Counting One-to-One Correspondence', 'A simple activity that builds number word awareness.', 8, '5–10 min', 'Small objects', 'Place 4 objects in a line; touch each as you count 1-2-3-4. Guide child''s hand to touch each. Counting with meaning, not reciting.', 'Understanding at this stage is built through direct experience, repeated many times. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sharing-practice-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Sharing Practice', 'A simple activity that builds playing near other children.', 8, '5–10 min', 'Blocks or similar', 'During play: ''You have 4 blocks. Can you give me 2?'' Guided sharing builds number concept alongside social skill.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('cooperative-building-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Cooperative Building', 'A simple activity that builds first turn-taking.', 8, '5–10 min', 'Blocks', 'Build something together: ''I put one block, you put one block.'' Turn-taking in construction is cooperative play at its clearest.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('feelings-vocabulary-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Feelings Vocabulary', 'An everyday activity that develops emotional vocabulary.', null, 'Ongoing', 'None', 'Name 5 emotions accurately this week: happy, sad, angry, scared, excited. Emotional vocabulary directly predicts social competence.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('pretend-play-elaboration-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Pretend Play Elaboration', 'A playful, repeatable activity for emotional expression and early social skills.', 13, '10–15 min', 'Soft toy', 'Join child''s pretend play and add a new element: ''The baby is sleeping: shall we sing her a lori?'' Extending the narrative.', 'Toddlers have very big feelings and almost no ability to manage them, so this is about support rather than teaching. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('frustration-script-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Frustration Script', 'An everyday activity that develops early emotional regulation.', 4, '3–5 min', 'None', 'Teach a specific phrase for frustration: ''I need help'' or ''Mujhe madad chahiye.'' Practice during calm: not during the moment.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('apology-practice-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Apology Practice', 'A playful, repeatable activity for emotional expression and early social skills.', 4, '3–5 min', 'None', 'When child hurts or upsets another: ''What could you say? How do you think they felt?'' Modelling, not forcing. Empathy precedes apology.', 'Toddlers have very big feelings and almost no ability to manage them, so this is about support rather than teaching. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('sensory-walk-barefoot-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sensory Walk Barefoot', 'A simple activity that builds tactile exploration.', 18, '15–20 min', 'None (outdoors)', 'Walk barefoot on grass, sand, and smooth pavement on the same outing. Noticing the difference is the sensory lesson.', 'This supports the sensory processing that underlies calm, settled behaviour. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('mixing-colours-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Mixing Colours', 'A simple activity that builds water play and sensory regulation.', 8, '5–10 min', 'Clear cups, water, food colouring', 'Add food colouring to water in clear cups and mix two together. Watching red + blue = purple is both science and sensory.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('musical-instruments-exploration-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Musical Instruments Exploration', 'An everyday activity that develops auditory processing.', 8, '5–10 min', 'Pots, boxes, metal containers', 'Pots, boxes, metal bowls: each makes a different sound. Let child experiment with what each material produces.', 'This supports the sensory processing that underlies calm, settled behaviour. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('clay-detailed-work-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Clay Detailed Work', 'A playful, repeatable activity for tactile exploration.', 13, '10–15 min', 'Atta dough and objects to press', 'Press small objects into dough to make impressions. Roll thin snakes. With an adult handing over and collecting the knife each time, cut with a blunt knife. Precision work in tactile medium.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('weighted-blanket-cuddle-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Weighted Blanket Cuddle', 'A playful, repeatable activity for sensory exploration and tolerance.', 8, '5–10 min', 'Heavy blanket', 'Wrap child in a heavy blanket on a lap. Deep pressure input is calming for the autonomic nervous system.', 'This supports the sensory processing that underlies calm, settled behaviour. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('independent-dressing-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Independent Dressing', 'A playful, repeatable activity for beginning to dress.', 13, '10–15 min', 'Clothing', 'By 24 months: pull trousers up and down, remove shoes and socks, help with shirts. All with support: independence is incremental.', 'This builds genuine independence at an age when wanting to be independent is at its peak. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('toilet-training-awareness-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Toilet Training Awareness', 'A playful, repeatable activity for toilet training readiness.', null, 'Ongoing', 'Potty (optional)', 'If interest appears: describe what toilet training involves. Let child see the process. No pressure: readiness signs should lead.', 'This builds genuine independence at an age when wanting to be independent is at its peak. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('jump-forward-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Jump Forward', 'A hands-on activity for developing jumping and explosive leg power.', 8, '5–10 min', 'None', 'Encourage jumping forward from standing, landing on both feet. Distance of jump increases each week as leg strength grows.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('walk-balance-beam-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Walk Balance Beam', 'A hands-on activity for developing static and dynamic balance.', 8, '5–10 min', 'Plank or tape line', 'A plank, a garden wall, or tape on the floor. Walk along without falling off. Balance on a narrow path is a 2.5-year skill.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('one-foot-i-m25_27', 'motor'::domain, 'm25_27'::age_band, 'One Foot I', 'A hands-on activity for developing jumping and explosive leg power.', 4, '3–5 min', 'None', 'Hold child''s hand and encourage hopping on one foot. Even one hop is the milestone beginning: don''t expect sustained hopping yet.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('catch-bounced-ball-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Catch Bounced Ball', 'An activity that builds throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Large ball', 'Bounce a large ball to child. Catching a bounced ball before a thrown one: the visual tracking time is longer.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('pedal-steering-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Pedal Steering', 'A hands-on activity for developing pedalling and steering.', 13, '10–15 min', 'Tricycle', 'Tricycle: practice steering around objects. Combining pedalling with directional control is a significant motor coordination step.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('animal-movement-play-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Animal Movement Play', 'A playful challenge that strengthens jumping and explosive leg power.', 8, '5–10 min', 'None', 'Move like different animals: frog jump, bear walk, crab walk, snake slither. Each uses different muscle groups and movement patterns.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-overhand-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Throw Overhand', 'An activity that builds running and speed control.', 8, '5–10 min', 'Ball', 'Demonstrate an overhand throw and let child try. Overhand requires trunk rotation: a very different movement than underhand.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('summersault-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Summersault', 'An activity that builds functional strength and carrying.', 4, '3–5 min', 'Soft mat or rug', 'Help child do a forward roll on a soft surface. Head tuck, push-off, and landing = vestibular, motor, and spatial all together.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('drawing-plus-sign-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Drawing Plus Sign', 'An activity that builds pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Show a + (cross) and let child try. Requires two directional lines crossing: harder than circle; appears around 30–36 months.', 'This strengthens the small muscles of the hand, which matters long before a pencil is ever picked up seriously. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('use-fork-independently-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Use Fork Independently', 'An activity that builds hand control and dexterity.', 13, '10–15 min', 'Fork, food', 'Fork for stabbing soft foods. The grip and stabbing force are different from a spoon: a distinct fine motor skill.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('dress-doll-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Dress Doll', 'A playful challenge that strengthens rotational and fastening control.', 8, '5–10 min', 'Doll with dressing features', 'Button, zip, and dress a doll. This is fine motor practice that feels purposeful and maintains engagement longer.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('fold-paper-half-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Fold Paper Half', 'A playful challenge that strengthens spatial placement.', 7, '5–8 min', 'Paper', 'Show folding a piece of paper in half and ask child to try. Aligning edges before folding requires spatial and motor precision.', 'This strengthens the small muscles of the hand, which matters long before a pencil is ever picked up seriously. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('sort-2-attributes-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Sort 2 Attributes', 'A playful challenge that strengthens bilateral coordination and spatial precision.', 8, '5–10 min', 'Blocks in multiple colours and sizes', 'Sort blocks by BOTH colour AND size together. Multi-attribute sorting is more demanding than single-attribute.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('lace-pattern-board-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Lace Pattern Board', 'A playful challenge that strengthens threading and hand-eye coordination.', 13, '10–15 min', 'Cardboard with holes and lace', 'Lace thread through holes to form a simple picture. Requires planning the sequence of holes to achieve the intended shape.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('tell-simple-story-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Tell Simple Story', 'A playful challenge that strengthens sentence building.', 8, '5–10 min', 'None', 'Ask child to tell a story about an animal they know. Even 2–3 sentences with a character is the emergence of narrative.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('ask-answer-questions-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Ask Answer Questions', 'A playful challenge that strengthens asking and answering questions.', 8, '5–10 min', 'None', 'Why does it rain?'' ''What would happen if…?'' Complex question forms are emerging: answer simply and turn it back.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('three-four-word-sentences-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Three- Four-Word Sentences', 'A playful challenge that strengthens sentence building.', null, 'Ongoing', 'None', 'Consistent 3–4 word sentences with grammar: ''I want the red ball.'' Grammar errors (''I goed'') are developmentally correct now.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('rhyming-detection-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Rhyming Detection', 'A playful challenge that strengthens asking and answering questions.', 7, '5–8 min', 'None', 'Does cat rhyme with bat? What about cat and dog?'' Detecting rhyme before producing it: typical at 25–30 months.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('describe-picture-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Describe Picture', 'A playful challenge that strengthens sentence building.', 7, '5–8 min', 'Picture or book illustration', 'Show a picture and ask ''What is happening here?'' Child describes scene: vocabulary, grammar, and observation all combined.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('first-last-name-m25_27', 'communication'::domain, 'm25_27'::age_band, 'First Last Name', 'An activity that builds asking and answering questions.', 4, '3–5 min', 'None', 'Practice saying full name. ''What is your full name?'' is a social comprehension milestone by age 3.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('conversation-questions-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Conversation Questions', 'A hands-on activity for developing asking and answering questions.', 8, '5–10 min', 'None', 'Have a 5-turn conversation where child asks at least one question. Asking is more advanced than answering.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('story-from-memory-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Story from Memory', 'An activity that builds asking and answering questions.', 8, '5–10 min', 'Familiar book', 'After reading a favourite book many times, ask child to ''read'' it to you from the pictures. Memory narrative is emerging.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('count-objects-5-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Count Objects 5', 'An activity that builds early number sense.', 7, '5–8 min', '5 small objects', 'Place up to 5 objects in a line and count together, touching each one. One-to-one correspondence solidifying now.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('basic-opposites-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Basic Opposites', 'An activity that builds comparing attributes.', 7, '5–8 min', 'Objects demonstrating contrast', 'Big/small, hot/cold, fast/slow, loud/quiet. Opposites build comparative conceptual thinking.', 'This is the age where children start to reason about why things happen, not just notice that they do. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('yesterday-today-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Yesterday Today', 'A hands-on activity for developing problem-solving and early concepts.', null, 'Ongoing', 'None', 'Yesterday we went to the park. Today we are home.'' Time concepts past/present solidify through consistent narration.', 'This is the age where children start to reason about why things happen, not just notice that they do. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('sort-4-categories-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Sort 4 Categories', 'A playful challenge that strengthens sorting and categorising.', 8, '5–10 min', 'Assorted household objects', 'Sort objects into 4 groups: food, animals, clothes, vehicles. Four-category sorting is sophisticated categorical thinking.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('pattern-extension-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Pattern Extension', 'An activity that builds working memory.', 7, '5–8 min', 'Coloured objects', 'Build red-blue-red-blue and leave a gap: ''What comes next?'' Pattern extension requires holding the rule in working memory.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('simple-addition-concept-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Simple Addition Concept', 'A playful challenge that strengthens early number sense.', 8, '5–10 min', 'Fruit or objects', 'Here are 2 bananas. I add 1 more. How many now?'' Concrete addition before abstract number.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('imaginary-friend-engagement-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Imaginary Friend Engagement', 'A hands-on activity for developing cooperative play.', 8, '5–10 min', 'None', 'If an imaginary friend appears, engage with them: ''What is their name?'' Imaginary companions support language, emotional, and social development.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('negotiate-trade-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Negotiate Trade', 'An activity that builds emotional regulation and social play.', 4, '3–5 min', 'None', 'When a conflict arises over a toy: ''What could you offer them to trade?'' Negotiation is a social skill that must be taught explicitly.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('brag-board-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Brag Board', 'An activity that builds emotional vocabulary and awareness.', 8, '5–10 min', 'Paper and display space', 'Create a display of child''s achievements (drawings, photos). ''You did all of these!'' Pride in accomplishment is a social-emotional milestone.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('role-play-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Role Play', 'A playful challenge that strengthens understanding limits.', 13, '10–15 min', 'Simple props', 'Set up a role-play scenario with simple props. Role-play at 25–30 months involves taking on another''s perspective.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('regulation-practice-pause-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Regulation Practice Pause', 'A playful challenge that strengthens emotional regulation.', 4, '3–5 min', 'None', 'When feelings escalate, say ''Let''s take a pause'' and model slow breathing together. Practice before it is needed.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('how-others-feel-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'How Others Feel', 'A hands-on activity for developing emotional regulation and social play.', 7, '5–8 min', 'Book or real situation', 'While reading or in real life: ''How do you think she felt when that happened?'' Perspective-taking practice.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('tissue-paper-collage-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Tissue Paper Collage', 'An activity that builds tactile discrimination.', 13, '10–15 min', 'Tissue paper, card, glue', 'Tear and paste coloured tissue paper onto card. Tearing texture, paper texture, and glue texture are layered sensory inputs.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('outdoor-water-play-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Outdoor Water Play', 'A playful challenge that strengthens water play and sensory regulation.', 18, '15–20 min', 'Water, watering can', 'Watering can, puddles, or garden tap. Child-directed water exploration is rich sensory and cause-effect play.', 'Sensory play remains genuinely developmental at this age, supporting both regulation and fine motor skill. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('texture-sorting-game-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Texture Sorting Game', 'A playful challenge that strengthens tactile discrimination.', 8, '5–10 min', '8 household objects', 'Gather 8 objects of varied texture. Sort into ''rough'' and ''smooth.'' Tactile discrimination is now a language + sensory task.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('proprioceptive-heavy-work-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Proprioceptive Heavy Work', 'A hands-on activity for developing vestibular and proprioceptive input.', 8, '5–10 min', 'Loaded bag or box', 'Carrying loaded backpack, pushing a box of books, pulling a weighted trolley. Heavy work regulates the nervous system.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('spin-spot-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Spin Spot', 'An activity that builds vestibular and proprioceptive input.', 4, '3–5 min', 'None', 'Spin with arms out, stop, try to stay balanced. Vestibular system input: intentional dizziness and recovery is regulating.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('brush-teeth-independently-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Brush Teeth Independently', 'An activity that builds hygiene routines.', 4, '3–5 min', 'Toothbrush and toothpaste', 'Let child brush their own teeth first, then parent finishes. Agency in the sequence builds cooperation with the hygiene routine.', 'Your toddler is now capable of real independence in daily routines, and doing so builds confidence as much as skill. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('toilet-training-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Toilet Training', 'A playful challenge that strengthens toilet independence.', null, 'Ongoing', 'Potty', 'If signs of readiness present (knowing when wet, interest in toilet), begin with simple potty introduction. Never forced.', 'This reduces the daily friction of routines by giving your child a genuine role in them. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('hop-one-foot-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Hop One Foot', 'A playful challenge that strengthens jumping and explosive leg power.', 7, '5–8 min', 'None', 'From one hop, build to 3–5 consecutive hops on the same foot. Each hop requires rebalancing: rapid balance adjustment developing.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('skip-i-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Skip I', 'A playful challenge that strengthens whole-body strength and coordination.', 8, '5–10 min', 'None', 'Most children gallop at 2.5 years and skip at 3.5. Practice gallop leading with each foot as the precursor.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('catch-thrown-ball-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Catch Thrown Ball', 'A hands-on activity for developing throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Medium ball', 'Graduate from bounced to thrown ball catching. Tracking the trajectory and adjusting arms = complex visual-motor planning.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('pedal-brake-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Pedal Brake', 'A playful challenge that strengthens pedalling and steering.', 13, '10–15 min', 'Tricycle', 'On a tricycle: practice pedalling and stopping at a marked line. Braking intentionally requires coordinated leg action.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('climb-ladder-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Climb Ladder', 'A hands-on activity for developing climbing and stepping coordination.', 8, '5–10 min', 'Climbing frame or playground', 'Staying close enough to spot and catch if needed, climb a ladder alternating hands and feet: the most complex locomotion pattern children this age attempt.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('jump-from-height-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Jump from Height', 'A hands-on activity for developing jumping and explosive leg power.', 4, '3–5 min', 'Low step', 'Standing close beside, ready to catch, let your child jump off a 30-cm step with both feet landing together. Judging safe heights and landing = spatial and motor cognition combined.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('balance-beam-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Balance Beam', 'A hands-on activity for developing static and dynamic balance.', 7, '5–8 min', 'Tape line', 'With you standing right beside them ready to steady them, walk a balance beam (tape line) with eyes closed for 2 steps. Eyes-closed balance challenges the proprioceptive system intensely.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('dodge-weave-game-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Dodge Weave Game', 'An activity that builds whole-body strength and coordination.', 13, '10–15 min', 'None', 'Chase game where child must dodge around obstacles. Reactive motor planning: responding to unexpected changes in a path.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('drawing-v-shape-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Drawing V Shape', 'A playful challenge that strengthens pre-writing control.', 7, '5–8 min', 'Crayon and paper', 'Show a V and ask child to copy. Angular shapes (V, then +, then triangle) appear in sequence after circle.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('draw-person-i-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Draw Person I', 'A playful challenge that strengthens pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Ask child to draw a person. Head + one other body part by 30 months = fine motor and representational thinking combined.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('scissors-straight-line-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Scissors Straight Line', 'An activity that builds pre-writing control.', 8, '5–10 min', 'Child scissors and paper', 'Cut along a straight line drawn on paper. Staying on the line requires visual monitoring while maintaining bilateral grip.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('peel-stick-labels-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Peel Stick Labels', 'A hands-on activity for developing threading and hand-eye coordination.', 8, '5–10 min', 'Stickers and paper', 'Peel self-adhesive stickers and place on a target. Two-stage finger action requiring precise coordination.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('build-bridge-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Build Bridge', 'A playful challenge that strengthens bilateral coordination and spatial precision.', 8, '5–10 min', 'Blocks', 'Demonstrate placing a block across two towers and ask child to build the same. Copying spatial models = architecture thinking.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('string-small-beads-m28_30', 'motor'::domain, 'm28_30'::age_band, 'String Small Beads', 'A playful challenge that strengthens pincer grasp and tool use.', 13, '10–15 min', 'Small beads + thin lace', 'Small beads on a thin lace. Fine pincer control plus visual targeting plus threading = high-demand fine motor task.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('500-word-vocabulary-m28_30', 'communication'::domain, 'm28_30'::age_band, '500+ Word Vocabulary', 'A hands-on activity for developing sentence building.', null, 'Ongoing', 'None', 'A 30-month-old typically has 450–600 words. Importantly, sentences are 3–5 words with mostly correct grammar.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('tell-stories-beginning-middle-end-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Tell Stories Beginning-Middle-End', 'A hands-on activity for developing sentence building and vocabulary.', 8, '5–10 min', 'None', 'Once there was a dog. He was hungry. He found some food and ate it.'' Three-part narrative structure is the target.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('because-if-sentences-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Because'' ''If'' Sentences', 'A hands-on activity for developing sentence building.', null, 'Ongoing', 'None', 'I''m tired because I didn''t sleep.'' ''If it rains, we''ll stay inside.'' Logical connectors mark a grammar milestone.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('how-something-works-m28_30', 'communication'::domain, 'm28_30'::age_band, 'How Something Works', 'An activity that builds sentence building and vocabulary.', 8, '5–10 min', 'Any household object', 'How does a tap work?'' Let child explain from their own understanding. Explanatory language is emerging.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('rhyme-production-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Rhyme Production', 'A playful challenge that strengthens rhythm and rhyme awareness.', 7, '5–8 min', 'None', 'I say cat: you say something that rhymes.'' Production (not just detection) of rhymes = phonological awareness step.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('letter-name-recognition-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Letter Name Recognition', 'A playful challenge that strengthens sentence building and vocabulary.', 7, '5–8 min', 'Paper with child''s name in large letters', 'Recognise the first letter of own name in print. This is enough letter knowledge to celebrate at 30 months.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('complex-question-response-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Complex Question Response', 'A hands-on activity for developing asking and answering questions.', 8, '5–10 min', 'None', 'What would you do if it was raining and you wanted to go outside?'' Hypothetical thinking + language combined.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('storytelling-from-memory-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Storytelling from Memory', 'A hands-on activity for developing narrative comprehension.', 8, '5–10 min', 'Familiar book', 'Retell a favourite story from memory using the book''s pictures as prompts. 3-event sequence is the typical recall at this age.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('count-10-meaning-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Count 10 Meaning', 'A hands-on activity for developing early number sense.', 7, '5–8 min', '10 small objects', 'Count 10 objects touching each one. At 30 months, 10-object counting with one-to-one correspondence is an achievable goal.', 'This is the age where children start to reason about why things happen, not just notice that they do. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('concept-same-different-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Concept Same Different', 'An activity that builds sorting and categorising.', 7, '5–8 min', 'Pairs of matching and non-matching objects', 'Are these the same or different?'': with objects that are clearly one or the other. Comparative language + cognition.', 'This is the age where children start to reason about why things happen, not just notice that they do. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('categorise-function-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Categorise Function', 'A playful challenge that strengthens sorting and categorising.', 8, '5–10 min', 'Household objects', 'Group things that you eat, things you wear, things you sit on. Sorting by function is more abstract than sorting by appearance.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('on-under-behind-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'On, Under, Behind', 'An activity that builds sequencing.', 7, '5–8 min', 'Cup and book', 'Put the cup on the book. Now under the book.'' Following spatial prepositions in sequence.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('morning-afternoon-evening-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Morning, Afternoon, Evening', 'A playful challenge that strengthens problem-solving and early concepts.', 7, '5–8 min', 'None', 'What do we do in the morning? What happens in the evening?'' Time-of-day sequencing before days of the week.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('simple-inference-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Simple Inference', 'An activity that builds cause-and-effect reasoning.', 8, '5–10 min', 'Picture book', 'While reading: ''Why is the bear sad?'': answer not in the text but inferrable from pictures. Early inferential thinking.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('play-small-group-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Play Small Group', 'A playful challenge that strengthens cooperative play.', 18, '15–20 min', 'None', 'Facilitate play in a group of 3. Children this age can begin brief cooperative interaction: note who initiates and who follows.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('express-feelings-words-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Express Feelings Words', 'A hands-on activity for developing emotional vocabulary and awareness.', null, 'Ongoing', 'None', 'Mujhe gussa aa raha hai'' or ''I feel scared.'' Verbal emotion expression before or instead of physical expression.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('help-younger-child-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Help Younger Child', 'A playful challenge that strengthens early empathy.', 8, '5–10 min', 'None', 'When a younger child needs help with something child can do: ''Can you show them how to stack the blocks?'' Pro-social seed.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP')
